const express = require('express');
const app = express();

// PostgreSQL client for health checks
const { Pool } = require('pg');
const pool = new Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://localhost:5432/production'
});

pool.on('error', (err) => {
  console.error('Unexpected error on idle client', err);
});

app.get('/healthz', async (req, res) => {
  try {
    // Perform a simple query to check DB connectivity
    const result = await pool.query('SELECT NOW()');
    if (result.rows && result.rows.length > 0) {
      res.status(200).json({ db: 'ok' });
    } else {
      res.status(503).json({ db: 'not ok' });
    }
  } catch (err) {
    console.error('Health check failed:', err);
    res.status(503).json({ db: 'not ok' });
  }
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

