#!/usr/bin/env node

// Test healthz endpoint
require('dotenv').config();
const axios = require('axios');

const PORT = 3000;

async function testHealthz() {
  console.log('Testing /healthz endpoint...\n');

  try {
    const response = await axios.get(`http://localhost:${PORT}/healthz`);
    console.log('Status:', response.status);
    console.log('Response:', JSON.stringify(response.data, null, 2));

    if (response.status === 200 && response.data.db === 'ok') {
      console.log('\n✓ /healthz returns 200 + {"db":"ok"} when Postgres is up');
    } else {
      console.log('\n✗ Unexpected response');
      process.exit(1);
    }
  } catch (error) {
    if (error.code === 'ECONNREFUSED') {
      console.error('\n✗ Server is not running. Please start it with: node app.js');
      process.exit(1);
    }
    console.error('Request failed:', error.message);
    if (error.response) {
      console.error('Status:', error.response.status);
      console.error('Response:', JSON.stringify(error.response.data, null, 2));
    }
    process.exit(1);
  }
}

testHealthz();

#!/usr/bin/env node

// Test healthz endpoint
const axios = require('axios');

const PORT = 3000;
const DATABASE_URL = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

// Set the DATABASE_URL before requiring app to ensure the connection is configured
process.env.DATABASE_URL = DATABASE_URL;

const app = require('./app');

const server = app.listen(PORT, () => {
  console.log('Server is running on port', PORT);
  console.log('Testing /healthz endpoint...\n');

  // Wait a moment for database connection check
  setTimeout(() => {
    axios.get(`http://localhost:3000/healthz`)
      .then(response => {
        server.close();
        console.log('Status:', response.status);
        console.log('Response:', JSON.stringify(response.data, null, 2));

        if (response.status === 200 && response.data.db === 'ok') {
          console.log('\n✓ /healthz returns 200 + {"db":"ok"} when Postgres is up');
          process.exit(0);
        } else {
          console.log('\n✗ Unexpected response');
          process.exit(1);
        }
      })
      .catch(error => {
        server.close();
        if (error.code === 'ECONNREFUSED') {
          console.error('\n✗ Server is not running.');
          process.exit(1);
        }
        console.error('Request failed:', error.message);
        if (error.response) {
          console.error('Status:', error.response.status);
          console.error('Response:', JSON.stringify(error.response.data, null, 2));
        }
        process.exit(1);
      });
  }, 1500);
});

{
  "name": "api",
  "version": "1.0.0",
  "description": "API with healthz endpoint",
  "main": "app.js",
  "scripts": {
    "start": "node app.js"
  },
  "dependencies": {
    "express": "^4.18.2",
