  }
}

const express = require('express');
const pg = require('pg');
const { Pool } = pg;

const app = express();
const PORT = process.env.PORT || 3000;

// Load configuration from environment
const databaseUrl = process.env.DATABASE_URL;

// Create PostgreSQL connection pool
const pool = new Pool({
  connectionString: databaseUrl,
});

// Middleware to parse JSON
app.use(express.json());

/**
 * /healthz endpoint for Kubernetes readiness probe
 * Returns 200 if PostgreSQL is reachable, 503 otherwise
 */
app.get('/healthz', async (req, res) => {
  try {
    const client = await pool.connect();
    try {
      // Test the database connection
      await client.query('SELECT NOW()');
      res.status(200).json({ db: 'ok' });
    } catch (dbError) {
      console.error('Health check failed:', dbError.message);
      res.status(503).json({ db: 'down', error: dbError.message });
    } finally {
      client.release();
    }
  } catch (connectionError) {
    console.error('Health check connection failed:', connectionError.message);
    res.status(503).json({ db: 'unreachable', error: connectionError.message });
  }
});

// Start the server
app.listen(PORT, () => {
  console.log(`API server running on http://localhost:${PORT}`);
  console.log(`Health check endpoint: http://localhost:${PORT}/healthz`);
});

