const { Pool } = require('pg');
const app = express();

// Database connection pool for health checks
let dbPool;
const isTestEnv = process.env.NODE_ENV === 'test';

async function initializeDbPool() {
  if (isTestEnv) {
    // In test/development use the provided synthetic credentials
    dbPool = new Pool({
      connectionString: process.env.DATABASE_URL,
      max: 10,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });
  }

  // Test the database connection
  try {
    if (dbPool) {
      await dbPool.query('SELECT 1');
      console.log('Database connection established');
    }
  } catch (err) {
    console.error('Database connection failed:', err.message);
    throw err;
  }
}

// Health check endpoint - returns 200 when DB is up, 503 when down
app.get('/healthz', async (req, res) => {
  try {
    if (!dbPool || isTestEnv) {
      // In test/dev, just verify the pool was initialized
      if (!dbPool) {
        return res.status(503).json({ db: 'unavailable' });
      }
    }

    // Ping the database
    await dbPool.query('SELECT 1');
    res.status(200).json({ db: 'ok' });
  } catch (err) {
    console.error('Health check failed:', err.message);
    res.status(503).json({ db: 'unavailable' });
  }
