// Health check endpoint for Kubernetes readiness/liveness probes
app.get('/healthz', async (req, res) => {
  try {
    // Parse DATABASE_URL from environment
    const databaseUrl = process.env.DATABASE_URL;

    if (!databaseUrl) {
      console.error('DATABASE_URL environment variable not set');
      return res.status(503).json({ status: 'unhealthy', reason: 'DATABASE_URL not set' });
    }

    // Parse database URL (postgres://user:pass@host:port/db)
    const url = new URL(databaseUrl);
    const { hostname, port, username, password } = url;

    // Validate PostgreSQL connection parameters
    if (!hostname || !username || !password) {
      console.error('Invalid DATABASE_URL format');
      return res.status(503).json({ status: 'unhealthy', reason: 'Invalid DATABASE_URL format' });
    }

    // Import pg to test connection
    const { Client } = require('pg');

    // Create minimal connection for health check
    const client = new Client({
      host: hostname,
      port: port || 5432,
      user: username,
      password: password,
    });

    // Test connection with timeout
    let connectionTimedOut = false;
    const connectionTimeout = setTimeout(() => {
      connectionTimedOut = true;
      client.end();
    }, 5000); // 5 second timeout

    try {
      await client.connect();
      clearTimeout(connectionTimeout);

      // Basic query to verify database is responsive
      await client.query('SELECT 1');

      client.end();

      return res.status(200).json({ db: 'ok' });
    } catch (connectionError) {
      clearTimeout(connectionTimeout);
      client.end();
      console.error('PostgreSQL connection failed:', connectionError.message);
      return res.status(503).json({ status: 'unhealthy', reason: connectionError.message });
    }
  } catch (error) {
    console.error('Health check failed:', error);
    return res.status(503).json({ status: 'unhealthy', reason: 'Internal health check error' });
  }
});

