const express = require('express');
const app = express();

// Database check function
async function checkDatabase() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    return { ok: false, message: 'DATABASE_URL not configured' };
  }

  try {
    // Extract connection parameters from DATABASE_URL
    const urlParts = databaseUrl.split('@');
    if (urlParts.length < 2) {
      return { ok: false, message: 'Invalid DATABASE_URL format' };
    }

    // Extract host and database from the URL
    const auth = urlParts[0].split('://')[1].split(':');
    const [host, ...pathParts] = urlParts[1].split('/');
    const database = pathParts[0] || 'production';

    // Try a simple TCP connection to the database port
    // This is a lightweight check - we just verify the host is reachable
    const net = require('net');

    return new Promise((resolve) => {
      const socket = new net.Socket();
      let timeout;

      socket.on('connect', () => {
        clearTimeout(timeout);
        socket.destroy();
        resolve({ ok: true });
      });

      socket.on('error', () => {
        clearTimeout(timeout);
        resolve({ ok: false, message: 'Cannot connect to database' });
      });

      timeout = setTimeout(() => {
        socket.destroy();
        resolve({ ok: false, message: 'Database connection timeout' });
      }, 2000);

      // Parse port from host (defaults to 5432 for Postgres)
      const hostParts = host.split(':');
      const port = hostParts[hostParts.length - 1] || 5432;

      socket.connect({ host: hostParts[0], port: parseInt(port) });
    });
  } catch (error) {
    return { ok: false, message: error.message };
  }
}

