  try {
    // Check if DATABASE_URL environment variable is set
    const databaseUrl = process.env.DATABASE_URL;

    if (!databaseUrl) {
      console.warn('DATABASE_URL environment variable not set');
      return res.status(503).json({ db: 'error', message: 'DATABASE_URL not configured' });
    }

    // Parse the DATABASE_URL to extract the connection parameters
    // Format: postgres://user:password@host:port/database
    const postgresUrl = new URL(databaseUrl);

    // Extract connection details
    const host = postgresUrl.hostname || 'localhost';
    const port = postgresUrl.port || 5432;
    const user = postgresUrl.username;
    const password = postgresUrl.password;
    const database = postgresUrl.pathname.slice(1); // Remove leading '/'

