      lastStatus = 'error';
      console.log(`✗ Health check FAILED: ${err.message}`);
      res.status(503).json({ status: 'error', message: 'db_check_failed' });
    } finally {
      await pool.end();
    }
  });

  return app;
}

// Run health check test
