input.new_string:
const express = require('express');
const net = require('net');
const app = express();

// Health check endpoint for Kubernetes readiness probe
app.get('/healthz', async (req, res) => {
  try {
    // Parse database URL to get host and port
    const databaseUrl = process.env.DATABASE_URL;
    if (!databaseUrl) {
      throw new Error('DATABASE_URL not set');
    }

    // Parse postgres://user:pass@host:port/dbname
    const urlMatch = databaseUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/.+/);
    if (!urlMatch) {
      throw new Error('Invalid DATABASE_URL format');
    }

    const [, user, password, host, port] = urlMatch;

    // Return "ok" if database is reachable (TCP connection succeeds)
    const client = net.connect(parseInt(port), host, () => {
      client.destroy();
      res.json({ db: 'ok' }).status(200);
    });

    client.on('error', () => {
      throw new Error('Failed to connect to database');
    });

    // Set timeout for the TCP connection attempt
    setTimeout(() => {
      if (client.writable) {
        client.destroy();
        throw new Error('Database connection timeout');
      }
    }, 1000);

  } catch (err) {
    console.error('Database health check failed:', err.message);
    res.status(503).json({ error: 'database unreachable' });
  }
});

